/*
 * A075745  Numbers n such that 210*n + 13 is prime.
 * https://oeis.org/A075745
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = k where k is the nth nonnegative integer such that 210*k
 *            + 13 is prime (OEIS A075745). The sequence is generated by a
 *            simple sieve/check; no closed form
 * Range:     u8 n <= 2, u16 n <= 138, u32 n <= 79, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/is_prime_big.h"      /* bool is_prime_big(seq_t n) */

seq_t a(idx_t n)
{
    /* Static cache of found values */
    static seq_t *cache = NULL;       /* array of k values */
    static size_t  cached_sz = 0;     /* number of stored values */
    static size_t  cached_cap = 0;    /* allocated capacity */
    static idx_t   next_k = 0;        /* next candidate k to test */

    /* Grow cache to required size if necessary (threads not considered) */
    if (cached_sz < (size_t)n)
    {
        while (cached_sz < (size_t)n)
        {
            /* Check primality of 210*k + 13 */
            seq_t cand = (seq_t)next_k * 210 + 13;
            if (is_prime_big(cand))
            {
                /* Ensure capacity */
                if (cached_sz == cached_cap)
                {
                    size_t new_cap = cached_cap ? cached_cap * 2 : 16;
                    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                    if (!tmp)
                    {
                        /* Allocation failed – abort */
                        abort();
                    }
                    cache = tmp;
                    cached_cap = new_cap;
                }
                /* Store the found k */
                cache[cached_sz++] = (seq_t)next_k;
            }
            next_k++;
        }
    }

    return cache[n - 1];   /* seq_t cache is 0‑based, n is 1‑based */
}
